def calculate_a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    k = n // 2
    if n % 2 == 0:
        # n = 2k (Even)
        result = 2 * calculate_a(k, memo) + k
    else:
        # n = 2k + 1 (Odd)
        # k is floor(n/2), k+1 is ceil(n/2)
        result = calculate_a(k, memo) + calculate_a(k + 1, memo) + k

    memo[n] = result
    return result

N_max = 40
memo = {}
results = {}

for n in range(1, N_max + 1):
    results[n] = calculate_a(n, memo)

print("n\ta_n")
for n, a_n in results.items():
    print(f"{n}\t{a_n}")

# Also calculate a_2025 one last time for verification if it hasn't been stored
a_2025_check = calculate_a(2025, memo)
print(f"\na_2025 calculated again: {a_2025_check}")

